// SetEmp of the empresaFilial to the related item.
// Sets o.R.Emp to related.
// Adds o to related.R.EmpEmpresaFilials.
func (o *EmpresaFilial) SetEmp(ctx context.Context, exec boil.ContextExecutor, insert bool, related *Empresa) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE `empresa_filial` SET %s WHERE %s",
		strmangle.SetParamNames("`", "`", 0, []string{"emp_id"}),
		strmangle.WhereClause("`", "`", 0, empresaFilialPrimaryKeyColumns),
	)
	values := []interface{}{related.EmpID, o.EmfID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.EmpID, related.EmpID)
	if o.R == nil {
		o.R = &empresaFilialR{
			Emp: related,
		}
	} else {
		o.R.Emp = related
	}

	if related.R == nil {
		related.R = &empresaR{
			EmpEmpresaFilials: EmpresaFilialSlice{o},
		}
	} else {
		related.R.EmpEmpresaFilials = append(related.R.EmpEmpresaFilials, o)
	}

	return nil
}

// RemoveEmp relationship.
// Sets o.R.Emp to nil.
// Removes o from all passed in related items' relationships struct.
func (o *EmpresaFilial) RemoveEmp(ctx context.Context, exec boil.ContextExecutor, related *Empresa) error {
	var err error

	queries.SetScanner(&o.EmpID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("emp_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Emp = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.EmpEmpresaFilials {
		if queries.Equal(o.EmpID, ri.EmpID) {
			continue
		}

		ln := len(related.R.EmpEmpresaFilials)
		if ln > 1 && i < ln-1 {
			related.R.EmpEmpresaFilials[i] = related.R.EmpEmpresaFilials[ln-1]
		}
		related.R.EmpEmpresaFilials = related.R.EmpEmpresaFilials[:ln-1]
		break
	}
	return nil
}

