// SetEmfChecklists removes all previously related items of the
// empresa_filial replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Emf's EmfChecklists accordingly.
// Replaces o.R.EmfChecklists with related.
// Sets related.R.Emf's EmfChecklists accordingly.
func (o *EmpresaFilial) SetEmfChecklists(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*Checklist) error {
	query := "update `checklist` set `emf_id` = null where `emf_id` = ?"
	values := []interface{}{o.EmfID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.EmfChecklists {
			queries.SetScanner(&rel.EmfID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Emf = nil
		}
		o.R.EmfChecklists = nil
	}

	return o.AddEmfChecklists(ctx, exec, insert, related...)
}

// RemoveEmfChecklists relationships from objects passed in.
// Removes related items from R.EmfChecklists (uses pointer comparison, removal does not keep order)
// Sets related.R.Emf.
func (o *EmpresaFilial) RemoveEmfChecklists(ctx context.Context, exec boil.ContextExecutor, related ...*Checklist) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.EmfID, nil)
		if rel.R != nil {
			rel.R.Emf = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("emf_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.EmfChecklists {
			if rel != ri {
				continue
			}

			ln := len(o.R.EmfChecklists)
			if ln > 1 && i < ln-1 {
				o.R.EmfChecklists[i] = o.R.EmfChecklists[ln-1]
			}
			o.R.EmfChecklists = o.R.EmfChecklists[:ln-1]
			break
		}
	}

	return nil
}

