// SetEmfContratoEntidades removes all previously related items of the
// empresa_filial replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Emf's EmfContratoEntidades accordingly.
// Replaces o.R.EmfContratoEntidades with related.
// Sets related.R.Emf's EmfContratoEntidades accordingly.
func (o *EmpresaFilial) SetEmfContratoEntidades(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*ContratoEntidade) error {
	query := "update `contrato_entidade` set `emf_id` = null where `emf_id` = ?"
	values := []interface{}{o.EmfID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.EmfContratoEntidades {
			queries.SetScanner(&rel.EmfID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Emf = nil
		}
		o.R.EmfContratoEntidades = nil
	}

	return o.AddEmfContratoEntidades(ctx, exec, insert, related...)
}

// RemoveEmfContratoEntidades relationships from objects passed in.
// Removes related items from R.EmfContratoEntidades (uses pointer comparison, removal does not keep order)
// Sets related.R.Emf.
func (o *EmpresaFilial) RemoveEmfContratoEntidades(ctx context.Context, exec boil.ContextExecutor, related ...*ContratoEntidade) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.EmfID, nil)
		if rel.R != nil {
			rel.R.Emf = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("emf_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.EmfContratoEntidades {
			if rel != ri {
				continue
			}

			ln := len(o.R.EmfContratoEntidades)
			if ln > 1 && i < ln-1 {
				o.R.EmfContratoEntidades[i] = o.R.EmfContratoEntidades[ln-1]
			}
			o.R.EmfContratoEntidades = o.R.EmfContratoEntidades[:ln-1]
			break
		}
	}

	return nil
}

