// SetEmfSistemas removes all previously related items of the
// empresa_filial replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Emf's EmfSistemas accordingly.
// Replaces o.R.EmfSistemas with related.
// Sets related.R.Emf's EmfSistemas accordingly.
func (o *EmpresaFilial) SetEmfSistemas(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*Sistema) error {
	query := "update `sistema` set `emf_id` = null where `emf_id` = ?"
	values := []interface{}{o.EmfID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.EmfSistemas {
			queries.SetScanner(&rel.EmfID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Emf = nil
		}
		o.R.EmfSistemas = nil
	}

	return o.AddEmfSistemas(ctx, exec, insert, related...)
}

// RemoveEmfSistemas relationships from objects passed in.
// Removes related items from R.EmfSistemas (uses pointer comparison, removal does not keep order)
// Sets related.R.Emf.
func (o *EmpresaFilial) RemoveEmfSistemas(ctx context.Context, exec boil.ContextExecutor, related ...*Sistema) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.EmfID, nil)
		if rel.R != nil {
			rel.R.Emf = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("emf_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.EmfSistemas {
			if rel != ri {
				continue
			}

			ln := len(o.R.EmfSistemas)
			if ln > 1 && i < ln-1 {
				o.R.EmfSistemas[i] = o.R.EmfSistemas[ln-1]
			}
			o.R.EmfSistemas = o.R.EmfSistemas[:ln-1]
			break
		}
	}

	return nil
}

